function suggestOriginIata(text) {
    const s = String(text || '').toLowerCase();
    if (!s.trim()) return '';
    const keys = Object.keys(CITY_IATA).sort((a, b) => b.length - a.length);
    for (const k of keys) { if (s.includes(k)) return CITY_IATA[k]; }
    return '';
}
function cleanIata(v, fallback) {
    const m = String(v || '').toUpperCase().match(/[A-Z]{3}/);
    return m ? m[0] : (fallback || '');
}
function cleanFlightDate(v) {
    const m = String(v || '').match(/(\d{4})-(\d{2})-(\d{2})/);
    return m ? `${m[1]}-${m[2]}-${m[3]}` : '';
}
// Google Flights PREFILLED search. Verified format:
//   https://www.google.com/travel/flights?q=Flights%20from%20BOS%20to%20ZAG%20on%202026-12-03
function buildGoogleFlightsUrl(origin, dest, depart, ret) {
    let q = `Flights from ${origin} to ${dest}`;
    if (depart) q += ` on ${depart}`;
    if (ret) q += ` returning ${ret}`;
    return 'https://www.google.com/travel/flights?q=' + encodeURIComponent(q);
}
// Skyscanner PREFILLED search. Path format (lowercase IATA + yymmdd):
//   https://www.skyscanner.net/transport/flights/bos/zag/261203/261206/
function buildSkyscannerUrl(origin, dest, depart, ret) {
    const o = String(origin || '').toLowerCase(), d = String(dest || '').toLowerCase();
    if (o.length !== 3 || d.length !== 3) return 'https://www.skyscanner.net/';
    const yymmdd = (iso) => { const m = String(iso || '').match(/(\d{4})-(\d{2})-(\d{2})/); return m ? (m[1].slice(2) + m[2] + m[3]) : ''; };
    let url = `https://www.skyscanner.net/transport/flights/${o}/${d}/`;
    const dd = yymmdd(depart), rr = yymmdd(ret);
    if (dd) url += dd + '/';
    if (dd && rr) url += rr + '/';
    return url;
}
// Resolve a speaker's flight search context: destination defaults to ZAG (editable),
// origin suggested from the institution, dates as stored. Both deep links are prefilled.
function speakerFlightContext(sp) {
    const origin = cleanIata(sp.origin_iata, '') || suggestOriginIata(sp.institution || '');
    const dest = cleanIata(sp.flight_dest_iata, 'ZAG');
    const depart = cleanFlightDate(sp.flight_depart_date);
    const ret = cleanFlightDate(sp.flight_return_date);
    return {
        origin_iata: origin,
        origin_suggested: suggestOriginIata(sp.institution || ''),
        dest_iata: dest,
        depart_date: depart,
        return_date: ret,
        google_url: (origin && dest) ? buildGoogleFlightsUrl(origin, dest, depart, ret) : null,
        skyscanner_url: (origin && dest) ? buildSkyscannerUrl(origin, dest, depart, ret) : null
    };
}

// ============================================================================
// AMADEUS LIVE FLIGHT OFFERS (queue 5a5i — the LIVE layer over the deep-links).
// Real flight-offer search per speaker: current airlines, times, layovers and
// EUR prices from the Amadeus Self-Service API. This is the "live search, not
// assumption search" boundary — we NEVER estimate, cache-fake or AI-guess a
// fare. With no key set every live route returns a clean 503 gate naming the
// exact owner actions, and the deep-links + manual quote table keep working.
//
// OWNER ACTION (mirrors the Meta boundary pattern):
//   1. Create a free Self-Service app at https://developers.amadeus.com
//   2. Set AMADEUS_API_KEY + AMADEUS_API_SECRET on the medx-admin-portal
//      Render service. Default host is the free test environment; set
//      AMADEUS_ENV=production once the Amadeus app is promoted.
// AMADEUS_BASE_URL exists ONLY so the local test harness can point the client
// at a mock — never set it in production.
const AMADEUS_ENV = (process.env.AMADEUS_ENV || 'test').toLowerCase() === 'production' ? 'production' : 'test';
const AMADEUS_BASE_URL = process.env.AMADEUS_BASE_URL
    || (AMADEUS_ENV === 'production' ? 'https://api.amadeus.com' : 'https://test.api.amadeus.com');
function amadeusConfigured() {
    return !!(process.env.AMADEUS_API_KEY && String(process.env.AMADEUS_API_KEY).trim()
        && process.env.AMADEUS_API_SECRET && String(process.env.AMADEUS_API_SECRET).trim());
}
// Exact ordered actions the owner still owes us — surfaced verbatim in the gate.
function amadeusMissingActions() {
    if (amadeusConfigured()) return [];
    return [
        'Create a free Amadeus Self-Service app at developers.amadeus.com (Flight Offers Search API).',
        'Set AMADEUS_API_KEY and AMADEUS_API_SECRET on the medx-admin-portal Render service.'
    ];
}
// OAuth2 client_credentials token, cached until 60s before expiry (~30 min tokens).
let amadeusTokenCache = { token: null, expiresAt: 0 };
async function amadeusToken() {
    if (amadeusTokenCache.token && Date.now() < amadeusTokenCache.expiresAt) return amadeusTokenCache.token;
    const body = new URLSearchParams({
        grant_type: 'client_credentials',
        client_id: process.env.AMADEUS_API_KEY,
        client_secret: process.env.AMADEUS_API_SECRET
    });
    const resp = await fetch(`${AMADEUS_BASE_URL}/v1/security/oauth2/token`, {
        method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: body.toString()
    });
    const json = await resp.json().catch(() => ({}));
    if (!resp.ok || !json.access_token) {
        throw new Error(`Amadeus auth failed (HTTP ${resp.status}) — check AMADEUS_API_KEY / AMADEUS_API_SECRET.`);
    }
    amadeusTokenCache = { token: json.access_token, expiresAt: Date.now() + Math.max(0, (json.expires_in || 1799) - 60) * 1000 };
    return amadeusTokenCache.token;
}
// ISO-8601 duration (PT11H20M) -> minutes. Amadeus uses it on itineraries + segments.
function isoDurationMinutes(d) {
    const m = String(d || '').match(/P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?/);
    if (!m) return 0;
    return (parseInt(m[1] || 0) * 1440) + (parseInt(m[2] || 0) * 60) + parseInt(m[3] || 0);
}
function fmtMinutes(min) {
    const h = Math.floor(min / 60), m = min % 60;
    return h ? `${h}h ${String(m).padStart(2, '0')}m` : `${m}m`;
}
// Normalize the raw Amadeus payload into the compact shape the panel renders and
// the pin endpoint snapshots. Carrier codes resolve through dictionaries.carriers.
function normalizeAmadeusOffers(payload) {
    const carriers = (payload.dictionaries && payload.dictionaries.carriers) || {};
    const carrierName = (code) => {
        const n = carriers[code];
        return n ? n.split(' ').map(w => w ? w[0] + w.slice(1).toLowerCase() : w).join(' ') : code;
    };
    return (payload.data || []).map(o => {
        const itineraries = (o.itineraries || []).map(it => {
            const segs = (it.segments || []).map(s => ({
                from: s.departure && s.departure.iataCode,
                to: s.arrival && s.arrival.iataCode,
                depart_at: s.departure && s.departure.at,
                arrive_at: s.arrival && s.arrival.at,
                carrier: s.carrierCode,
                carrier_name: carrierName(s.carrierCode),
                flight_number: `${s.carrierCode}${s.number || ''}`
            }));
            const stops = Math.max(0, segs.length - 1);
            const vias = segs.slice(0, -1).map(s => s.to).filter(Boolean);
            return {
                duration_minutes: isoDurationMinutes(it.duration),
                duration_label: fmtMinutes(isoDurationMinutes(it.duration)),
                stops, vias, segments: segs,
                summary: segs.length
                    ? `${segs[0].from}→${segs[segs.length - 1].to} · ${stops === 0 ? 'non-stop' : stops + ' stop' + (stops > 1 ? 's' : '') + (vias.length ? ' (' + vias.join(', ') + ')' : '')}`
                    : ''
            };
        });
        const airlines = [...new Set((o.validatingAirlineCodes || []).map(carrierName))];
        return {
            offer_id: o.id,
            price: Math.round(Number(o.price && (o.price.grandTotal || o.price.total)) * 100) / 100,
            currency: (o.price && o.price.currency) || 'EUR',
            airline: airlines.join(' / ') || (itineraries[0] && itineraries[0].segments[0] && itineraries[0].segments[0].carrier_name) || '',
            total_duration_minutes: itineraries.reduce((a, it) => a + it.duration_minutes, 0),
            max_stops: itineraries.reduce((a, it) => Math.max(a, it.stops), 0),
            itineraries
        };
    }).filter(o => isFinite(o.price) && o.price > 0);
}
// Tag the cheapest offer and the best price/duration/stops balance. Deterministic:
// balance score = price ratio + 0.9 * duration ratio + 0.15 per stop.
function tagFlightOffers(offers) {
    if (!offers.length) return offers;
    const minPrice = Math.min(...offers.map(o => o.price));
    const minDur = Math.max(1, Math.min(...offers.map(o => o.total_duration_minutes || 1)));
    let cheapest = null, best = null, bestScore = Infinity;
    for (const o of offers) {
        if (!cheapest || o.price < cheapest.price) cheapest = o;
        const score = (o.price / minPrice) + 0.9 * ((o.total_duration_minutes || minDur) / minDur) + 0.15 * (o.max_stops || 0);
        if (score < bestScore) { bestScore = score; best = o; }
    }
    if (cheapest) cheapest.tag_cheapest = true;
    if (best) best.tag_best = true;
    return offers;
}
// One live flight-offers search. Throws with a clean message on any API failure —
// callers translate that into a 502, never into a made-up fare.
async function amadeusSearchOffers({ origin, dest, depart, ret }) {
    const token = await amadeusToken();
    const params = new URLSearchParams({
        originLocationCode: origin,
        destinationLocationCode: dest,
        departureDate: depart,
        adults: '1',
        currencyCode: 'EUR',
        max: '20'
    });
    if (ret) params.set('returnDate', ret);
    const resp = await fetch(`${AMADEUS_BASE_URL}/v2/shopping/flight-offers?${params}`, {
        headers: { 'Authorization': `Bearer ${token}` }
    });
    const json = await resp.json().catch(() => ({}));
    if (!resp.ok) {
        const detail = json.errors && json.errors[0] && (json.errors[0].detail || json.errors[0].title);
        throw new Error(detail ? `Amadeus: ${detail}` : `Amadeus search failed (HTTP ${resp.status}).`);
    }
    return tagFlightOffers(normalizeAmadeusOffers(json));
}

// ============================================================================
// META (Instagram / Facebook) PUBLISHING BOUNDARY  (queue 5a8)
// The pr_posts scheduler can push a post straight to a Med&X Facebook Page and
// Instagram Business account via the Graph API. The real calls are fully wired
// but require owner-provided credentials (a long-lived Page access token, the
// Page ID, and the linked IG Business account id — see docs/social_api_spec.md).
// With those UNSET the boundary is a MOCK that names EXACTLY what the owner must
// provide. A global kill switch (pr_meta_settings.enabled) gates every real send;
// dry-run works regardless and LOGS the exact ordered Graph calls it WOULD make.
// A per-post drip_log marker (meta:<platform>:<id>) makes a real publish idempotent.
const META_GRAPH_BASE = 'https://graph.facebook.com/v21.0';
function getMetaSettings() {
    try {
        const r = query.get('SELECT * FROM pr_meta_settings WHERE id = 1');
        if (r) return r;
    } catch (e) {}
    return { id: 1, page_id: null, page_access_token: null, ig_user_id: null, enabled: 0 };
}
function metaHasToken() { const s = getMetaSettings(); return !!(s.page_access_token && String(s.page_access_token).trim()); }
function metaCanPublish(platform) {
    const s = getMetaSettings();
    if (!s.page_access_token) return false;
    if (platform === 'instagram') return !!s.ig_user_id;
    return !!s.page_id; // facebook
}
// Exact ordered actions the owner still owes us. Mirrors docs/social_api_spec.md.
function metaMissingActions() {
    const s = getMetaSettings();
    const out = [];
    if (!s.page_access_token) out.push('A long-lived Facebook Page access token from a Meta app with pages_manage_posts, pages_read_engagement, instagram_basic and instagram_content_publish.');
    if (!s.page_id) out.push('The numeric Facebook Page ID of the Med&X Page (enables Facebook publishing).');
    if (!s.ig_user_id) out.push('The Instagram Business account ID linked to that Page (enables Instagram publishing).');
    return out;
}
// Redact a token to its last 4 chars for logs/UI (never echo the secret).
function redactToken(t) { const s = String(t || ''); return s ? `****${s.slice(-4)}` : '(none)'; }
// Build the EXACT ordered Graph calls for one post, WITHOUT sending. IG needs a
// two-step container->publish; FB is a single feed/photos call. Bodies carry a
// redacted token so a dry-run is safe to display and log.
function buildMetaCalls(post) {
    const s = getMetaSettings();
    const platform = String(post.platform || '').toLowerCase();
    const message = [post.content_text || post.caption || '', post.hashtags || ''].filter(Boolean).join('\n\n').trim();
    const imageUrl = post.image_url || null;
    const calls = [];
    if (platform === 'instagram') {
        const ig = s.ig_user_id || '{IG_USER_ID}';
        if (!imageUrl) {
            calls.push({ step: 'blocked', note: 'Instagram requires an image or video. Add a hosted image to this post before publishing to Instagram.' });
            return { platform, calls };
        }
        calls.push({ step: 1, label: 'Create media container', method: 'POST',
            url: `${META_GRAPH_BASE}/${ig}/media`,
            body: { image_url: imageUrl, caption: message, access_token: redactToken(s.page_access_token) } });
        calls.push({ step: 2, label: 'Publish container', method: 'POST',
            url: `${META_GRAPH_BASE}/${ig}/media_publish`,
            body: { creation_id: '{from step 1: id}', access_token: redactToken(s.page_access_token) } });
    } else { // facebook (default)
        const pg = s.page_id || '{PAGE_ID}';
        if (imageUrl) {
            calls.push({ step: 1, label: 'Publish Page photo', method: 'POST',
                url: `${META_GRAPH_BASE}/${pg}/photos`,
                body: { url: imageUrl, caption: message, access_token: redactToken(s.page_access_token) } });
        } else {
            calls.push({ step: 1, label: 'Publish Page feed post', method: 'POST',
                url: `${META_GRAPH_BASE}/${pg}/feed`,
                body: { message, access_token: redactToken(s.page_access_token) } });
        }
    }
    return { platform, calls };
}
// Execute (or dry-run) the Graph calls for one post. NEVER throws. dryRun always
// works (logs + returns the planned calls, sends nothing). A real send is refused
// unless the kill switch is ON and the platform is fully configured.
async function publishToMeta(post, opts) {
    opts = opts || {};
    const platform = String(post.platform || '').toLowerCase();
    const plan = buildMetaCalls(post);
    const s = getMetaSettings();
    const blocked = plan.calls.find(c => c.step === 'blocked');
    if (blocked) return { ok: false, dryRun: !!opts.dryRun, status: 'blocked', note: blocked.note, calls: plan.calls };

    if (opts.dryRun) {
        console.log(`[Meta DryRun] ${platform} — would make ${plan.calls.length} Graph call(s):`, JSON.stringify(plan.calls));
        return {
            ok: true, dryRun: true, status: 'dry_run', configured: metaCanPublish(platform),
            note: metaCanPublish(platform)
                ? `Dry run only — nothing was sent. ${plan.calls.length} Graph call(s) logged. Turn the kill switch on to publish for real.`
                : `Dry run only — Meta is not fully connected yet. Still needed: ${metaMissingActions().join(' ')}`,
            calls: plan.calls
        };
    }
    // Real send path (untestable here without live credentials).
    if (!s.enabled) return { ok: false, dryRun: false, status: 'kill_switch_off', note: 'Meta publishing is turned off (kill switch). Turn it on in PR & Media, Meta publishing, to send for real.', calls: plan.calls };
    if (!metaCanPublish(platform)) return { ok: false, dryRun: false, status: 'not_configured', note: `Cannot publish to ${platform} yet. Still needed: ${metaMissingActions().join(' ')}`, calls: plan.calls };
    try {
        let creationId = null, externalId = null;
        for (const call of plan.calls) {
            const body = { ...call.body };
            if ('access_token' in body) body.access_token = s.page_access_token;
            if (body.creation_id === '{from step 1: id}') body.creation_id = creationId;
            const resp = await fetch(call.url, { method: call.method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
            const text = await resp.text().catch(() => '');
            let json = {}; try { json = JSON.parse(text); } catch (_) {}
            if (!resp.ok) return { ok: false, dryRun: false, status: 'failed', note: `Graph HTTP ${resp.status}: ${text.slice(0, 300)}`, calls: plan.calls };
            if (call.step === 1) creationId = json.id || null;
            externalId = json.id || externalId;
        }
        return { ok: true, dryRun: false, status: 'published', external_post_id: externalId, note: `Published to ${platform} via the Graph API.`, calls: plan.calls };
    } catch (e) {
        return { ok: false, dryRun: false, status: 'failed', note: 'Meta publish error: ' + e.message, calls: plan.calls };
    }
}


// ---- Hosted ticket-QR helpers (mirror of user-portal; the /qr/:id.png route lives there) ----
// Emails reference a hosted QR URL instead of a data: URI because Gmail/Outlook strip data: URIs.
// The PNG is also attached so the ticket survives image-blocking clients.
const QR_BASE_URL = process.env.USER_PORTAL_URL || 'https://medx-user-portal.onrender.com';
function qrImageUrl(regId) { return `${QR_BASE_URL}/qr/${regId}.png`; }

async function qrPngAttachment(payload) {
    try {
        const png = await QRCode.toBuffer(JSON.stringify(payload), { width: 560, margin: 2, color: { dark: '#000000', light: '#ffffff' } });
        return [{ filename: 'plexus-ticket-qr.png', content: png, type: 'image/png' }];
    } catch (e) {
        console.warn('QR attachment generation failed:', e.message);
        return [];
    }
}

function buildTicketQrBlock(regId, opts = {}) {
    const label = opts.label || 'Your Check-in QR Code';
    const caption = opts.caption || 'Present this code at the event entrance';
    return `
    <table width="100%" cellpadding="0" cellspacing="0" style="margin:26px 0;"><tr><td align="center">
        <table cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e6dfc8;border-radius:18px;overflow:hidden;box-shadow:0 3px 14px rgba(15,23,42,0.07);">
            <tr><td style="background:linear-gradient(90deg,#b8922e,#C9A962,#dfc070,#C9A962,#b8922e);height:4px;font-size:0;line-height:0;">&nbsp;</td></tr>
            <tr><td style="padding:22px 34px 6px;text-align:center;font-size:11px;font-weight:700;color:#C9A962;text-transform:uppercase;letter-spacing:2.5px;">${label}</td></tr>
            <tr><td align="center" style="padding:10px 34px 6px;text-align:center;">
                <img src="${qrImageUrl(regId)}" alt="Check-in QR code" width="220" height="220" style="display:block;margin:0 auto;border:0;" />
            </td></tr>
            <tr><td style="padding:0 34px 4px;text-align:center;font-size:12px;color:#94a3b8;letter-spacing:2px;font-family:'Courier New',monospace;">${String(regId).substring(0, 8).toUpperCase()}</td></tr>
            <tr><td style="padding:6px 34px 22px;text-align:center;font-size:12px;color:#64748b;line-height:1.6;">${caption}<br><span style="color:#94a3b8;">Your QR is also attached to this email — save it to your phone.</span></td></tr>
        </table>
    </td></tr></table>`;
}

// Generate a speaker invite code: SPK-XXXX-2026
function generateSpeakerInviteCode() {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no I/O/0/1 to avoid confusion
    let code = '';
    for (let i = 0; i < 4; i++) code += chars[Math.floor(Math.random() * chars.length)];
    return `SPK-${code}-2026`;
}

// Safety net: a single bad request must NOT take down the whole service. Node 15+ exits on an
// unhandled promise rejection (e.g. an async route that throws after its try/catch) — log instead.
process.on('unhandledRejection', (reason) => { console.error('[unhandledRejection]', (reason && reason.stack) || reason); });

const PORT = process.env.PORT || 3001;
const JWT_SECRET = process.env.JWT_SECRET || (process.env.NODE_ENV === 'development' ? 'medx-dev-secret' : (() => { console.error('FATAL: JWT_SECRET environment variable is required in production'); process.exit(1); })());

// Public marketing-website API (/api/public/*) is fetched cross-origin by the Med&X
// website (Netlify preview + production). Scope an explicit origin allowlist to these
// read-only endpoints ONLY, and register it BEFORE the global CORS policy so it owns the
// preflight for this path (the global policy is env-restricted in production and would
// otherwise short-circuit the OPTIONS request without an Access-Control-Allow-Origin
// header). This never opens CORS globally and never touches the Stripe/checkout/
// registration surfaces. See website audit B5.
const PUBLIC_API_ORIGINS = [
  'https://medx-website-preview.netlify.app',
  'https://www.medx.hr',
  'https://medx.hr'
];
app.use('/api/public', cors({ origin: PUBLIC_API_ORIGINS }));

// NEVER fall back to origin:true here — reflect-any-origin + credentials:true would let any
// site read authenticated admin responses the moment CORS_ORIGIN goes missing from the env.
app.use(cors({
  origin: process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',') : [
    'https://medx-admin-portal.onrender.com',
    'https://medx-user-portal.onrender.com',
    'http://localhost:3000', 'http://localhost:3001'
  ],
  credentials: true
}));

// Security headers via helmet — same posture as user-portal so the admin UI loads
// the same CDN scripts (Chart.js, FontAwesome, html5-qrcode, jsQR).
// Keep the whole admin service out of search engines. robots.txt alone leaves a bare
// URL listing in Google once the address is known; the noindex header makes Google drop it.
app.use((req, res, next) => { res.setHeader('X-Robots-Tag', 'noindex, nofollow'); next(); });
app.use(helmet({
    contentSecurityPolicy: {
        useDefaults: true,
        directives: {
            "default-src": ["'self'"],
            "script-src": [
                "'self'", "'unsafe-inline'", "'wasm-unsafe-eval'",
                "https://js.stripe.com", "https://m.stripe.network", "https://m.stripe.com",
                "https://cdn.jsdelivr.net", "https://cdnjs.cloudflare.com",
                "https://unpkg.com"
            ],
            "script-src-attr": ["'unsafe-inline'"],
            "style-src": [
                "'self'", "'unsafe-inline'",
                "https://fonts.googleapis.com", "https://cdnjs.cloudflare.com",
                "https://cdn.jsdelivr.net"
            ],
            "font-src": ["'self'", "data:", "https://fonts.gstatic.com", "https://cdnjs.cloudflare.com"],
            "img-src": ["'self'", "data:", "blob:", "https:"],
            "connect-src": [
                "'self'", "blob:",
                "https://api.stripe.com", "https://m.stripe.network", "https://r.stripe.com",
                "https://*.cloudinary.com",
                "https://www.gstatic.com",
                // The admin SPA calls the USER portal directly for member-DB actions
                // (gala refunds, Live Q&A). Without this, those fetches die on CSP.
                "https://medx-user-portal.onrender.com", "http://localhost:3001"
            ],
            "worker-src": ["'self'", "blob:"],
            "frame-src": [
                "'self'",
                "https://js.stripe.com", "https://hooks.stripe.com", "https://checkout.stripe.com"
            ],
            "form-action": ["'self'", "https://checkout.stripe.com"],
            "frame-ancestors": ["'none'"],
            "base-uri": ["'self'"],
            "object-src": ["'none'"],
            "upgrade-insecure-requests": []
        }
    },
    crossOriginEmbedderPolicy: false,
    crossOriginOpenerPolicy: { policy: "same-origin-allow-popups" },
    referrerPolicy: { policy: "strict-origin-when-cross-origin" }
}));

