// ===== Menu 14: fail loud when persistent object storage is missing in production =====
// On Render's free tier the local disk is EPHEMERAL — anything multer writes vanishes on the
// next redeploy or cold start. This portal writes uploads to disk, so CLOUDINARY_URL is the
// codebase-wide "persistence is configured" signal (see the storage health check). In
// production without it we refuse file uploads (503) instead of silently accepting a file that
// will be lost. Dev is unchanged, and parse-and-discard multipart posts (CSV imports) are exempt.
const IS_PRODUCTION = process.env.NODE_ENV === 'production' || !!process.env.RENDER;
const STORAGE_IS_EPHEMERAL = IS_PRODUCTION && !process.env.CLOUDINARY_URL;
if (STORAGE_IS_EPHEMERAL) {
    console.error('============================================================');
    console.error('  [Storage] ERROR: running in PRODUCTION with no persistent');
    console.error('  object store (CLOUDINARY_URL is unset). Uploaded files would');
    console.error('  be written to EPHEMERAL disk and lost on the next redeploy or');
    console.error('  restart. File-upload endpoints will return 503 until');
    console.error('  CLOUDINARY_URL is configured (see render.yaml / menu 14).');
    console.error('============================================================');
}
// Endpoints whose multipart body is parsed then discarded (never persisted) — always allowed.
const UPLOAD_EXEMPT_SUFFIXES = ['/import', '/prospects/preview'];
app.use((req, res, next) => {
    if (!STORAGE_IS_EPHEMERAL) return next();
    if (req.method !== 'POST' && req.method !== 'PUT' && req.method !== 'PATCH') return next();
    if (!(req.headers['content-type'] || '').includes('multipart/form-data')) return next();
    if (UPLOAD_EXEMPT_SUFFIXES.some(s => req.path.endsWith(s))) return next();
    return res.status(503).json({ error: 'File uploads are temporarily unavailable. Persistent storage is not configured, so an uploaded file would be lost on the next restart. Please contact the administrator.' });
});

// Create uploads directory
const uploadsDir = path.join(__dirname, 'uploads');
['abstracts', 'posters', 'documents', 'badges', 'photos', 'tickets', 'accelerator', 'chat', 'content-studio', 'spatial'].forEach(dir => {
    const dirPath = path.join(uploadsDir, dir);
    if (!fs.existsSync(dirPath)) fs.mkdirSync(dirPath, { recursive: true });
});

// Multer configuration
const storage = multer.diskStorage({
    destination: (req, file, cb) => cb(null, path.join(uploadsDir, req.params.type || 'documents')),
    filename: (req, file, cb) => cb(null, `${uuidv4()}${path.extname(file.originalname)}`)
});
const ALLOWED_MIME_TYPES = [
    'application/pdf',
    'image/jpeg', 'image/png', 'image/gif', 'image/webp',
    'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.ms-powerpoint', 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'text/plain', 'text/csv'
];
const upload = multer({
    storage,
    limits: { fileSize: 10 * 1024 * 1024 },
    fileFilter: (req, file, cb) => {
        if (ALLOWED_MIME_TYPES.includes(file.mimetype)) return cb(null, true);
        cb(new Error(`File type ${file.mimetype} not allowed. Accepted: PDF, images, Office documents, CSV.`));
    }
});

let db;
const SHARED_DB_PATH = path.join(__dirname, '../../shared/medx_portal.db');
const LOCAL_DB_PATH = path.join(__dirname, 'medx_portal.db');
const DB_PATH = process.env.DATABASE_PATH || (fs.existsSync(SHARED_DB_PATH) ? SHARED_DB_PATH : LOCAL_DB_PATH);

// Database helper — identical to sql.js version; shared/db.js handles translation
const query = {
    run: (sql, params = []) => { db.run(sql, params); saveDb(); },
    get: (sql, params = []) => {
        const stmt = db.prepare(sql);
        if (params.length) stmt.bind(params);
        if (stmt.step()) { const r = stmt.getAsObject(); stmt.free(); return r; }
        stmt.free(); return null;
    },
    all: (sql, params = []) => {
        const stmt = db.prepare(sql);
        if (params.length) stmt.bind(params);
        const rows = [];
        while (stmt.step()) rows.push(stmt.getAsObject());
        stmt.free(); return rows;
    }
};

// Once the production demo purge has run (app_state marker), the demo seed blocks must never
// re-arm — an emptied table would otherwise re-seed on the next boot, and the admin/user seed
// variants have drifted apart (the admin pr_posts INSERT crashes against the user-created
// schema). Fresh dev DBs have no marker, so local seeding keeps working.
function demoSeedsBlocked() {
    try { return !!query.get("SELECT 1 FROM app_state WHERE key='demo_purge_2026_07_25'"); }
    catch (e) { return false; }
}


// Active conference resolver (multi-year support) — used by the Plexus Settings
// price sync so admin price edits flow into the ticket_types rows of whichever
// year is live. REQUIRES the active row to have ticket tiers (so a ticketless or
// stray is_active=1 row can't capture the sync); falls back to plexus-2026.
function getActiveConference() {
    return query.get(`SELECT c.* FROM conferences c
                      WHERE c.is_active = 1 AND EXISTS (SELECT 1 FROM ticket_types t WHERE t.conference_id = c.id)
                      ORDER BY c.year DESC LIMIT 1`)
        || query.get("SELECT * FROM conferences WHERE slug = 'plexus-2026'");
}

let _syncTimer = null;
function saveDb() {
    // libsql auto-persists to local disk — schedule debounced Turso cloud sync
    if (process.env.TURSO_DATABASE_URL) {
        if (_syncTimer) clearTimeout(_syncTimer);
        _syncTimer = setTimeout(() => { db.sync(); }, 2000);
    }
}

