    // ===== Email verification tokens (member signup confirmation) =====
    // Byte-identical in both portal server.js files (shared Turso DB in prod). One row per issued
    // verification link. The user portal issues + consumes these (POST /api/auth/request-verification,
    // GET /api/auth/verify?token=), flipping users.email_verified=1 on a valid, unused, unexpired token.
    // Email sending goes through the shared sendEmail() mock boundary — in dev the link is logged, never
    // actually emailed. used_at is set once a token is redeemed so a given link works exactly once.
    db.run(`CREATE TABLE IF NOT EXISTS email_verifications (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        email TEXT,
        token TEXT NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        expires_at TEXT,
        used_at TEXT
    )`);

    // ===== Rewards economy — server-authoritative points ledger (menu: Rewards) =====
    // Byte-identical in both portal server.js files (shared Turso DB in prod). Points are NEVER a
    // mutable balance a client can set: a member's balance is SUM(delta) over points_ledger and
    // lifetime-earned is the sum of the positive rows. Every earn is idempotent on (reason, ref_id),
    // so the same payment, check-in, email-verification or profile-completion can only credit once.
    // reason is one of payment|checkin|profile|verify|admin_adjust|redeem; redeem writes a negative delta.
    db.run(`CREATE TABLE IF NOT EXISTS points_ledger (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        delta INTEGER NOT NULL,
        reason TEXT NOT NULL,
        ref_id TEXT,
        note TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);

    // One row per points-to-coupon redemption. The coupon itself is minted into promo_codes (the same
    // table the checkout rail already reads); this table is the member-facing record of what was spent
    // and when the coupon expires. status is one of active|used|expired|cancelled.
    db.run(`CREATE TABLE IF NOT EXISTS reward_redemptions (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        points_spent INTEGER NOT NULL,
        coupon_code TEXT NOT NULL,
        coupon_value_eur REAL NOT NULL,
        status TEXT DEFAULT 'active',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        expires_at TEXT
    )`);

    // Admin-adjustable economy knobs (earn rate, per-event earn amounts, redeem tiers as JSON, minimum
    // basket, coupon lifetime). Read by both portals; written by the admin rewards-settings endpoint.
    db.run(`CREATE TABLE IF NOT EXISTS rewards_settings (
        key TEXT PRIMARY KEY,
        value TEXT
    )`);

    // ===== NAG->DO action items (Action Center engine) =====
    // Byte-identical in both portal server.js files (shared Turso DB in prod). The admin daily
    // scan writes ACTION ITEMS here: overdue/soon tasks, unpaid registrations, gala guests missing
    // dietary info, stale project statuses, unanswered member messages, sponsor deliverables. Each
    // row carries a one-click DO action — action_kind + action_payload_json describe what the Action
    // Center button EXECUTES (queue an approval-gated email reminder, nudge the assignee, or deep
    // link). status is one of open|actioned|done|dismissed. A rescan reconciles: an item whose
    // underlying condition is fixed auto-resolves to done; dismissed items stay dismissed.
    db.run(`CREATE TABLE IF NOT EXISTS nag_items (
        id TEXT PRIMARY KEY,
        kind TEXT NOT NULL,
        subject_id TEXT,
        title TEXT NOT NULL,
        action_kind TEXT,
        action_payload_json TEXT,
        assignee TEXT,
        status TEXT DEFAULT 'open',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        resolved_at TEXT
    )`);

    // ===== Lifecycle automations: drip idempotency, confirm-seat, waitlist auto-offer =====
    // Byte-identical in both portal server.js files (shared Turso DB in prod). These back the
    // welcome-drip / verification-nudge engines (user portal) and the confirm-your-seat + waitlist
    // auto-offer engines (admin portal). Declared in BOTH so the shared Turso table always exists
    // regardless of which portal boots first; each engine only writes the tables it owns.

    // One row per (user, lifecycle-email kind) — makes every drip/nudge enqueue exactly-once.
    // kind: welcome | interests | verify_nudge_1 | verify_nudge_2. UNIQUE(user_id, kind) is the
    // idempotency guard (INSERT OR IGNORE + getRowsModified()==1 means "first time" and gates the send).
    db.run(`CREATE TABLE IF NOT EXISTS drip_log (
        id TEXT PRIMARY KEY,
        user_id TEXT,
        email TEXT,
        kind TEXT NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(user_id, kind)
    )`);

    // Confirm-your-seat (free-event no-show killer). One row per (reg_id, event_key). status is one
    // of pending | confirmed | released. token backs the public one-click GET /api/public/confirm-seat.
    db.run(`CREATE TABLE IF NOT EXISTS seat_confirmations (
        id TEXT PRIMARY KEY,
        reg_id TEXT NOT NULL,
        event_key TEXT NOT NULL DEFAULT 'plexus',
        email TEXT,
        name TEXT,
        token TEXT NOT NULL,
        status TEXT DEFAULT 'pending',
        sent_at TEXT,
        reminder_sent_at TEXT,
        confirmed_at TEXT,
        released_at TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(reg_id, event_key)
    )`);

    // Waitlist auto-offer. When a seat releases, the next waiting person gets a 48h claim link.
    // status is one of offered | claimed | expired. claim_token backs the public GET
    // /api/public/claim-seat, which deep-links (never auto-creates) the frozen registration flow.
    db.run(`CREATE TABLE IF NOT EXISTS waitlist_offers (
        id TEXT PRIMARY KEY,
        waitlist_id TEXT,
        event_key TEXT NOT NULL DEFAULT 'plexus',
        email TEXT,
        name TEXT,
        ticket_type TEXT,
        claim_token TEXT NOT NULL,
        status TEXT DEFAULT 'offered',
        source_reg_id TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        expires_at TEXT,
        claimed_at TEXT
    )`);

    // Admin-tunable automation knobs (confirm-seat T-offsets, engine on/off). key/value; value is a
    // short string or JSON. Read/written by the admin portal; declared in both for boot-order safety.
    db.run(`CREATE TABLE IF NOT EXISTS automation_config (
        key TEXT PRIMARY KEY,
        value TEXT,
        updated_at TEXT,
        updated_by TEXT
    )`);

    // First-party, privacy-friendly site analytics — AGGREGATE counters only (no accounts, no
    // cookies, no IPs, no per-visitor rows), so it is GDPR-clean by design. The public beacon
    // POST /api/public/pv (user portal) UPSERTs one row per (day, path, referrer_domain, device),
    // incrementing count; the admin Site-analytics card reads it via GET /api/admin/analytics.
    // Declared in BOTH portals (shared Turso DB) so the table exists regardless of which boots
    // first; only the user portal ever writes to it. UNIQUE(day,path,referrer_domain,device) is
    // the UPSERT target that keeps one running counter per bucket.
    db.run(`CREATE TABLE IF NOT EXISTS page_views (
        id TEXT PRIMARY KEY,
        day TEXT NOT NULL,
        path TEXT NOT NULL,
        referrer_domain TEXT NOT NULL DEFAULT 'direct',
        device TEXT NOT NULL DEFAULT 'desktop',
        count INTEGER NOT NULL DEFAULT 0,
        UNIQUE(day, path, referrer_domain, device)
    )`);

    // ===== Post-event automation: round tracking + one-question feedback =====
    // Byte-identical in both portal server.js files (shared Turso DB in prod). The admin portal runs
    // the post-event round (stages the thank-you / missed / certificate / feedback batches into the
    // shared outbox, and issues certificates rows the member portal reads); the public feedback GET
    // (served by the admin backend) writes event_feedback. Declared in BOTH so the shared table always
    // exists regardless of which portal boots first; each engine only writes the tables it owns.

    // One row per (event_key, reg_id, kind) — the idempotency marker that makes re-running a round
    // exactly-once: an email is only staged, and a certificate only issued, when the marker is newly
    // inserted (INSERT OR IGNORE + getRowsModified()==1). kind: thankyou | missed | cert | feedback.
    // batch_id links the marker to the outbox batch it belongs to; ref carries the certificate id or
    // feedback token so the round can find what it created without re-deriving it.
    db.run(`CREATE TABLE IF NOT EXISTS post_event_log (
        id TEXT PRIMARY KEY,
        event_key TEXT NOT NULL DEFAULT 'plexus',
        reg_id TEXT NOT NULL,
        kind TEXT NOT NULL,
        batch_id TEXT,
        ref TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(event_key, reg_id, kind)
    )`);

    // One row per feedback invite. token backs the public GET /api/public/feedback?token=&score=1-10;
    // score is clamped to 1..10 and recorded at most once per token (responded_at gates a re-tap). The
    // admin post-event card aggregates AVG(score) + COUNT(score) per event_key. A row is created with
    // score NULL when the feedback batch is staged, then filled in when the attendee taps their score.
    db.run(`CREATE TABLE IF NOT EXISTS event_feedback (
        id TEXT PRIMARY KEY,
        event_key TEXT NOT NULL DEFAULT 'plexus',
        reg_id TEXT,
        email TEXT,
        token TEXT UNIQUE,
        score INTEGER,
        comment TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        responded_at TEXT
    )`);

    // planner_plans: the Content Planner wizard stores one row per generated plan. answers_json is the
    // parsed conversation, plan_json is the {items:[...]} calendar (each item image-carrying). status is
    // draft -> approved. Declared in the mirror block so the shared Turso DB always has it regardless of
    // which portal boots first; only the admin portal writes it (the Content Planner lives there).
    db.run(`CREATE TABLE IF NOT EXISTS planner_plans (
        id TEXT PRIMARY KEY,
        period_start TEXT,
        period_end TEXT,
        answers_json TEXT,
        plan_json TEXT,
        status TEXT DEFAULT 'draft',
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);

    // org_settings: ONE org-level key/value store shared by BOTH portals (Turso). Currently one key,
    // 'signature' — the founder's real signature stored as a self-contained data:image/png base64 URL so
    // EVERY signed artifact (council invitations, attendance certificates, any future signed page) renders
    // it same-origin with no canvas taint and no dependence on a per-service disk (Render disks are
    // ephemeral; the shared DB is the durable, cross-portal source of truth). The admin portal writes it
    // (Settings -> Signature); both portals read it via GET /api/org/signature.
    db.run(`CREATE TABLE IF NOT EXISTS org_settings (
        key TEXT PRIMARY KEY,
        value TEXT,
        updated_at TEXT
    )`);
    // ====================== SCHEMA-MIRROR:END ======================

    // ====================== UNIFIED PER-EVENT CHECK-IN + WALLET (admin-only) ======================
    // These three tables live OUTSIDE the SCHEMA-MIRROR block (admin portal owns the door scanner).
    //  - checkin_events : the gate list a Plexus Week pass can be scanned at (the scanner's event
    //    selector + per-gate validity windows for the not-yet-active / expired states).
    //  - event_checkins : the per-(registration,event) check-in. UNIQUE(reg,event) makes each scan an
    //    atomic single-winner insert, so two devices can't double-admit the same ticket+event, and
    //    scanning at Conference never consumes Gala access.
    //  - checkin_scans  : the append-only audit of EVERY scan attempt (valid/invalid/already/…),
    //    with the token, attendee, event, admin, device and manual-override info.
    db.run(`CREATE TABLE IF NOT EXISTS checkin_events (
        id TEXT PRIMARY KEY,
        event_key TEXT NOT NULL UNIQUE,
        label TEXT NOT NULL,
        conference_slug TEXT DEFAULT 'plexus-2026',
        starts_at TEXT, ends_at TEXT,
        valid_from TEXT, valid_until TEXT,
        is_active INTEGER DEFAULT 1,
        sort_order INTEGER DEFAULT 0,
        created_at TEXT DEFAULT (datetime('now'))
    )`);
    db.run(`CREATE TABLE IF NOT EXISTS event_checkins (
        id TEXT PRIMARY KEY,
        registration_id TEXT NOT NULL,
        event_key TEXT NOT NULL,
        checkin_token TEXT,
        checked_in_at TEXT DEFAULT (datetime('now')),
        admin_id TEXT, admin_email TEXT,
        device TEXT,
        method TEXT DEFAULT 'qr',
        override_reason TEXT,
        UNIQUE(registration_id, event_key)
    )`);
    db.run(`CREATE TABLE IF NOT EXISTS checkin_scans (
        id TEXT PRIMARY KEY,
        token TEXT, registration_id TEXT, event_key TEXT,
        result TEXT,
        method TEXT DEFAULT 'qr',
        admin_id TEXT, admin_email TEXT,
        device TEXT,
        is_override INTEGER DEFAULT 0, override_reason TEXT,
        created_at TEXT DEFAULT (datetime('now'))
    )`);
    try { db.run('CREATE INDEX IF NOT EXISTS idx_event_checkins_reg ON event_checkins(registration_id)'); } catch(e) {}
    try { db.run('CREATE INDEX IF NOT EXISTS idx_checkin_scans_reg ON checkin_scans(registration_id, created_at)'); } catch(e) {}

    // Seed the four Plexus Week 2026 gates (idempotent by event_key). starts_at/ends_at are the event
    // schedule (they drive the scanner's default-gate selection by date). valid_from/valid_until are the
    // OPTIONAL scan-enforcement window and are intentionally left NULL by default: a gate always admits
    // until the owner explicitly sets a window, so a stale/future date can never lock out the real door.
    // The owner opts into the not-yet-active / expired states per gate via PUT /api/admin/checkin/events.
    const _seedGates = [
        ['conference', 'Plexus Week — Conference', '2026-12-04T08:00:00', '2026-12-05T20:00:00', 1],
        ['gala',       'Plexus Gala Evening',      '2026-12-05T19:00:00', '2026-12-05T23:59:00', 2],
        ['donor',      'Plexus Donor Night',       '2026-12-04T19:00:00', '2026-12-04T23:00:00', 3],
        ['bridges',    'Building Bridges',         null, null, 4]
    ];
    for (const g of _seedGates) {
        try {
            if (!query.get('SELECT 1 x FROM checkin_events WHERE event_key = ?', [g[0]])) {
                db.run(`INSERT INTO checkin_events (id, event_key, label, starts_at, ends_at, sort_order)
                        VALUES (?,?,?,?,?,?)`, [require('crypto').randomUUID(), g[0], g[1], g[2], g[3], g[4]]);
            }
        } catch(e) { /* one gate failing never blocks boot */ }
    }

    // Backfill the crypto admission token for every existing registration missing one (one-time; NULL-only).
    try {
        const _needTok = query.all("SELECT id FROM registrations WHERE checkin_token IS NULL OR checkin_token = ''");
        for (const r of _needTok) {
            db.run('UPDATE registrations SET checkin_token = ? WHERE id = ?', [require('crypto').randomBytes(24).toString('hex'), r.id]);
        }
        if (_needTok.length) { saveDb(); console.log('[checkin] backfilled ' + _needTok.length + ' registration token(s)'); }
    } catch(e) { console.error('[checkin] token backfill skipped:', e.message); }

    // ====================== CME / HLK ACCREDITATION (queue 5a5c) ======================
    // Croatian Medical Chamber (Hrvatska liječnička komora / HLK) CME accreditation. These two
    // tables live OUTSIDE the SCHEMA-MIRROR block but are declared IDENTICALLY in BOTH portal
    // server.js files: the user portal writes physician CME submissions (post-registration attach)
    // and reads a member's own record plus the active event's accreditation status; the admin
    // portal sets the per-edition accreditation flag and exports consented attendees for chamber
    // reporting. Idempotent (CREATE TABLE IF NOT EXISTS). CME credit is OFFICIAL chamber credit and
    // is deliberately DECOUPLED from the internal rewards/points gamification — nothing here ever
    // writes points_ledger and no rewards code reads these tables.
    db.run(`CREATE TABLE IF NOT EXISTS cme_accreditations (
        conference_id TEXT PRIMARY KEY,
        is_accredited INTEGER DEFAULT 0,
        points_value REAL,
        accreditation_number TEXT,
        updated_by TEXT,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
    // One physician CME record per registration (registration_id UNIQUE — post-submit attach, upsert).
    // date_of_birth + oib are sensitive personal data collected ONLY with the member's explicit,
    // un-pre-ticked consent (consent = 1 + consent_at timestamp + consent_purpose) for the sole stated
    // purpose of reporting CME credit to the chamber. When CME_ENC_KEY is set they are stored
    // AES-256-GCM-encrypted at rest (enc = 1, value carries the 'gcm:' scheme prefix); with no key they
    // fall back to plaintext (enc = 0) — see cmeEncrypt/cmeDecrypt. Admin-only visibility; the member
    // reads their own row via /api/plexus/cme/my.
    db.run(`CREATE TABLE IF NOT EXISTS cme_submissions (
        id TEXT PRIMARY KEY,
        registration_id TEXT UNIQUE,
        conference_id TEXT,
        user_id TEXT,
        date_of_birth TEXT,
        oib TEXT,
        enc INTEGER DEFAULT 0,
        consent INTEGER DEFAULT 0,
        consent_at TEXT,
        consent_purpose TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
    db.run(`CREATE INDEX IF NOT EXISTS idx_cme_sub_conf ON cme_submissions(conference_id)`);
    db.run(`CREATE INDEX IF NOT EXISTS idx_cme_sub_user ON cme_submissions(user_id)`);

    // ====================== ADMIN INVITES + FOUNDER USAGE (Team Access) ======================
    // ADMIN-ONLY, OUTSIDE the SCHEMA-MIRROR block (the user portal never reads any of this).
    // users.must_change_password: set when an account is provisioned with a temporary invite
    // password (POST /api/admin/team/invite) — the auth middleware locks every route except
    // POST /api/auth/change-password (+ /api/auth/me) until the member sets their own password.
    // users.is_founder: server-side gate for the founder-only usage panel (see founderOnly).
    // Guarded, additive ALTERs — same pattern as the login-visibility pass.
    try { db.run('ALTER TABLE users ADD COLUMN must_change_password INTEGER DEFAULT 0'); } catch(e) {}
    try { db.run('ALTER TABLE users ADD COLUMN is_founder INTEGER DEFAULT 0'); } catch(e) {}
    // users.allowed_sections: per-admin section permissions (see PERMISSION_SECTIONS /
    // sectionDenied next to the auth middleware). NULL = full access — every admin that existed
    // before this feature keeps working exactly as before; '[]' = Home only (new invitees);
    // otherwise a JSON array of section ids the founder granted from Team Access → Permissions.
    try { db.run('ALTER TABLE users ADD COLUMN allowed_sections TEXT'); } catch(e) {}

    // Per-admin per-UTC-day portal presence, accumulated from visible-tab heartbeats (~60s
    // cadence — see POST /api/team/heartbeat). Each beat credits the real elapsed gap since the
    // previous beat, capped at 90s, so an overnight sleep gap or abandoned tab never inflates
    // the totals. last_beat_at carries the gap measurement across day boundaries.
    db.run(`CREATE TABLE IF NOT EXISTS admin_usage (
        user_id TEXT NOT NULL,
        day TEXT NOT NULL,
        seconds INTEGER DEFAULT 0,
        heartbeats INTEGER DEFAULT 0,
        last_beat_at TEXT,
        PRIMARY KEY (user_id, day)
    )`);

    // ========================================================================
    // EVENT-DAY STAFF TRACKING (queue 5a5j) — ADMIN-ONLY, OUTSIDE the SCHEMA-MIRROR block.
    // Live, event-day-scoped location sharing for the ops team. Every tracked person is a
    // portal user with is_admin OR is_staff (speakers/guests are never users here, so they can
    // never opt in — they appear on the map only indirectly, as the subject of a pairing chip).
    // Only the admin portal reads/writes these tables; the shared Turso DB gets them on admin
    // boot. The one cross-portal hop is the stale check-in PUSH, which rides the EXISTING shared
    // push_outbox (the user portal, which holds VAPID, drains + sends it). Positions are
    // LIVE-ONLY: hard-deleted when the event day ends (auto) or an admin taps Purge.
    db.run(`CREATE TABLE IF NOT EXISTS staff_tracking_settings (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        active INTEGER DEFAULT 0,
        event_label TEXT,
        ends_at TEXT,
        stale_minutes INTEGER DEFAULT 10,
        updated_by TEXT,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
    db.run("INSERT OR IGNORE INTO staff_tracking_settings (id, active, stale_minutes) VALUES (1, 0, 10)");

    db.run(`CREATE TABLE IF NOT EXISTS staff_tracking_consent (
        user_id TEXT PRIMARY KEY,
        enabled INTEGER DEFAULT 0,
        consent_at TEXT,
        display_name TEXT,
        last_prompt_at TEXT,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )`);

    db.run(`CREATE TABLE IF NOT EXISTS staff_positions (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        lat REAL NOT NULL,
        lng REAL NOT NULL,
        accuracy REAL,
        heading REAL,
        speed REAL,
        recorded_at TEXT DEFAULT CURRENT_TIMESTAMP,
        client_ts TEXT
    )`);
    db.run(`CREATE INDEX IF NOT EXISTS idx_staff_positions_user ON staff_positions(user_id, recorded_at)`);

    db.run(`CREATE TABLE IF NOT EXISTS staff_pairings (
        id TEXT PRIMARY KEY,
        staff_user_id TEXT NOT NULL,
        speaker_id TEXT,
        guest_name TEXT,
        note TEXT,
        status TEXT DEFAULT 'assigned',
        confirmed_at TEXT,
        created_by TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);

    // ========================================================================
    // GAME DAY MODE — ADMIN-ONLY, OUTSIDE the SCHEMA-MIRROR block.
    // A focused event-day operations layer: while an event (a conference row or the Gala)
    // is live, the admin portal lands everyone on ONE dashboard for THAT event only, with a
    // polling ops chat (one main channel + fixed team rooms) and magic-link volunteer invites
    // that open a locked-down game-day view with per-invite permission grants. Only the admin
    // portal reads/writes these tables; the shared Turso DB gets them on admin boot. The user
    // portal never reads them (scripts/check-schema-sync.sh stays green).
    db.run(`CREATE TABLE IF NOT EXISTS gameday_settings (
        id INTEGER PRIMARY KEY CHECK (id = 1),
        mode TEXT DEFAULT 'off',
        test_event_key TEXT,
        updated_by TEXT,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
    db.run("INSERT OR IGNORE INTO gameday_settings (id, mode) VALUES (1, 'off')");

    // Ops chat. channel is a fixed key ('glavni' or a team key) — no channels table needed;
    // the catalog lives in code (GAMEDAY_TEAMS/GAMEDAY_CHANNELS) so both roles stay in sync.
    db.run(`CREATE TABLE IF NOT EXISTS gameday_messages (
        id TEXT PRIMARY KEY,
        channel TEXT NOT NULL,
        author_name TEXT,
        author_kind TEXT DEFAULT 'admin',
        team TEXT,
        body TEXT NOT NULL,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
    db.run(`CREATE INDEX IF NOT EXISTS idx_gameday_messages_channel ON gameday_messages(channel, created_at)`);

    // Volunteer magic-link invites. token is the whole credential (crypto-random hex, unique);
    // grants_json is a JSON array of extra-permission keys from GAMEDAY_GRANTS. revoked=1 kills
    // the link AND any live session (the volunteer auth middleware re-checks this row per request).
    db.run(`CREATE TABLE IF NOT EXISTS gameday_invites (
        id TEXT PRIMARY KEY,
        token TEXT UNIQUE NOT NULL,
        name TEXT NOT NULL,
        email TEXT,
        team TEXT,
        grants_json TEXT DEFAULT '[]',
        created_by TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        last_seen_at TEXT,
        revoked INTEGER DEFAULT 0
    )`);

    // ADMIN-ONLY: Content studio — a log of pieces made in the creation studio (graphics, slideshow
    // videos, PDFs). Not shared with the user portal. The generated file lives under
    // /uploads/content-studio; this row records it for the "recent creations" gallery and links a piece
    // to any pr_content_calendar row it was scheduled into.
    db.run(`CREATE TABLE IF NOT EXISTS content_studio_assets (
        id TEXT PRIMARY KEY,
        kind TEXT NOT NULL,
        template TEXT,
        aspect TEXT,
        project TEXT,
        title TEXT,
        caption TEXT,
        asset_url TEXT NOT NULL,
        mime TEXT,
        bytes INTEGER DEFAULT 0,
        calendar_id TEXT,
        created_by TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);

    // ADMIN-ONLY: team file storage. The bytes live IN the database (base64 in a TEXT column),
    // NOT on disk — Render's free-tier disk is wiped on every redeploy, and Alen's explicit
    // requirement was "I don't want them to get wiped out". 5MB per file keeps rows sane; bigger
    // things belong on SharePoint. Sits OUTSIDE the SCHEMA-MIRROR (user portal never reads it).
    db.run(`CREATE TABLE IF NOT EXISTS team_files (
        id TEXT PRIMARY KEY,
        scope TEXT NOT NULL DEFAULT 'general',
        name TEXT NOT NULL,
        mime TEXT,
        size INTEGER DEFAULT 0,
        data TEXT NOT NULL,
        uploaded_by TEXT,
        uploaded_by_name TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);

    // ADMIN-ONLY: Advisory Council invitations — the print-grade invitation artifact generated in the
    // Content Studio ("Council Invitations"). One row per designed invitation. The rendered artifact
    // lives under /uploads/content-studio (as a content_studio_assets 'invitation' row too); this row
    // is the saved list the studio shows, and carries status draft|sent. NOT shared with the user
    // portal (it sits OUTSIDE the SCHEMA-MIRROR block, so scripts/check-schema-sync.sh stays green).
    db.run(`CREATE TABLE IF NOT EXISTS council_invitations (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        title TEXT,
        institution TEXT,
        language TEXT DEFAULT 'en',
        personal_sentence TEXT,
        email TEXT,
        status TEXT DEFAULT 'draft',
        asset_url TEXT,
        asset_id TEXT,
        outbox_batch TEXT,
        created_by TEXT,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        updated_at TEXT
    )`);

    // ADMIN-ONLY: Gala → table-picker invite sync ledger. One row per invite this portal
    // created (or revoked) in the picker's Firestore `invites` collection (project
    // plexus-gala-tables; doc id = the guest's personal 16-hex token, link =
    // https://plexus-tables.netlify.app/?t=<token>). email is stored lowercased.
    // invited_email_sent gates the approval-gated "Odaberite svoj stol" mail (0 = invite
    // exists but the guest has not been mailed yet); revoked_at is stamped when a refund/
    // rejection/deletion makes the guest ineligible and the engine deletes the Firestore
    // doc. Also the future feed for send_invites-style mailing audits. NOT shared with the
    // user portal (OUTSIDE the SCHEMA-MIRROR block, so check-schema-sync.sh stays green).
    db.run(`CREATE TABLE IF NOT EXISTS gala_picker_invites (
        id TEXT PRIMARY KEY,
        email TEXT NOT NULL,
        name TEXT,
        token TEXT NOT NULL,
        max_party INTEGER DEFAULT 3,
        invited_email_sent INTEGER DEFAULT 0,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        revoked_at TEXT
    )`);

    // ADMIN-ONLY: Council Invitations settings (key/value — currently only 'signature_url', the
    // founder's uploaded real-signature PNG that replaces the built-in script signature on every
    // invitation render). OUTSIDE the SCHEMA-MIRROR block, same as council_invitations above.
    db.run(`CREATE TABLE IF NOT EXISTS council_settings (
        key TEXT PRIMARY KEY,
        value TEXT,
        updated_at TEXT
    )`);

    // One-time migration: promote the old per-feature council signature (a PNG file under /uploads, from
    // 8616d9c) into the ONE org-level signature (org_settings 'signature', a self-contained base64 data
    // URL). Runs only when the org signature is not yet set; best-effort — a missing file simply leaves
    // the org unset, and every artifact falls back to clean blank space above the typed name.
    try {
        const haveOrg = query.get("SELECT value FROM org_settings WHERE key = 'signature'");
        const legacy = query.get("SELECT value FROM council_settings WHERE key = 'signature_url'");
        if ((!haveOrg || !haveOrg.value) && legacy && legacy.value) {
            const local = path.join(__dirname, String(legacy.value).replace(/^\/+/, ''));
            if (fs.existsSync(local)) {
                const b = fs.readFileSync(local);
                const isPng = b.length > 8 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4E && b[3] === 0x47;
                if (isPng) {
                    db.run("INSERT OR REPLACE INTO org_settings (key, value, updated_at) VALUES ('signature', ?, datetime('now'))", ['data:image/png;base64,' + b.toString('base64')]);
                    saveDb();
                    console.log('[org] migrated council signature -> org_settings');
                }
            }
        }
    } catch (e) { /* migration is best-effort */ }

