    // follow-up flag in the UI. Lives OUTSIDE the SCHEMA-MIRROR block (admin-only, not shared).
    db.run(`CREATE TABLE IF NOT EXISTS gala_menu_options (
        id TEXT PRIMARY KEY,
        label TEXT NOT NULL,
        keywords TEXT,
        sort_order INTEGER DEFAULT 0,
        is_default INTEGER DEFAULT 0,
        active INTEGER DEFAULT 1,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
    try {
        const moCount = query.get("SELECT COUNT(*) AS c FROM gala_menu_options")?.c || 0;
        if (!moCount) {
            const seed = [
                ['Meat / Standard', 'meat,standard,regular,omnivore,none,no special,no dietary,classic,no restrictions', 0, 1],
                ['Fish', 'fish,pescatarian,seafood,salmon', 1, 0],
                ['Vegetarian', 'vegetarian,veggie,lacto,ovo', 2, 0],
                ['Vegan', 'vegan,plant-based,plant based', 3, 0],
            ];
            for (const [label, kw, so, isd] of seed) {
                db.run("INSERT INTO gala_menu_options (id, label, keywords, sort_order, is_default, active) VALUES (?,?,?,?,?,1)",
                    [uuidv4(), label, kw, so, isd]);
            }
        }
    } catch (e) { console.warn('[gala menu options seed]', e.message); }

    // ONE-TIME TEST-DATA WIPE (mirror of user-portal migration) — clears fake Gala
    // and Croatians Abroad registrations from pre-launch testing. Idempotent via
    // app_state marker; will not re-run after first execution.
    try {
        db.run(`CREATE TABLE IF NOT EXISTS app_state (
            key TEXT PRIMARY KEY,
            value TEXT,
            updated_at TEXT DEFAULT CURRENT_TIMESTAMP
        )`);
        // Scoped to TEST-TAGGED rows only (see user-portal server.js for rationale) — a
        // blanket DELETE would erase real paid guests on a fresh DB / marker-less replica.
        // Ensure referenced columns exist first (fresh-DB base tables may lack invoice_number).
        try { db.run('ALTER TABLE gala_registrations ADD COLUMN invoice_number TEXT'); } catch(e) {}
        try { db.run('ALTER TABLE croatians_abroad_registrations ADD COLUMN invoice_number TEXT'); } catch(e) {}
        try { db.run('ALTER TABLE croatians_abroad_registrations ADD COLUMN notes TEXT'); } catch(e) {}
        const TEST_GALA_WHERE = "WHERE COALESCE(requests,'') LIKE '%TEST%' OR COALESCE(invoice_number,'') LIKE '%TEST%'";
        const TEST_CA_WHERE = "WHERE COALESCE(notes,'') LIKE '%TEST%' OR COALESCE(invoice_number,'') LIKE '%TEST%'";
        const wipeMarker = query.get("SELECT value FROM app_state WHERE key = 'gala_test_wipe_2026_06_02'");
        if (!wipeMarker) {
            const gCount = query.get(`SELECT COUNT(*) as c FROM gala_registrations ${TEST_GALA_WHERE}`)?.c || 0;
            const caCount = query.get(`SELECT COUNT(*) as c FROM croatians_abroad_registrations ${TEST_CA_WHERE}`)?.c || 0;
            db.run(`DELETE FROM gala_registrations ${TEST_GALA_WHERE}`);
            db.run(`DELETE FROM croatians_abroad_registrations ${TEST_CA_WHERE}`);
            db.run("INSERT INTO app_state (key, value, updated_at) VALUES ('gala_test_wipe_2026_06_02', ?, ?)",
                [`gala_registrations:${gCount},croatians_abroad_registrations:${caCount}`, new Date().toISOString()]);
            console.log(`[wipe] Test-tagged data cleared: ${gCount} gala + ${caCount} croatians_abroad rows.`);
        }
        const wipeMarkerV2 = query.get("SELECT value FROM app_state WHERE key = 'gala_test_wipe_2026_06_03_v2'");
        if (!wipeMarkerV2) {
            const gCount2 = query.get(`SELECT COUNT(*) as c FROM gala_registrations ${TEST_GALA_WHERE}`)?.c || 0;
            const caCount2 = query.get(`SELECT COUNT(*) as c FROM croatians_abroad_registrations ${TEST_CA_WHERE}`)?.c || 0;
            db.run(`DELETE FROM gala_registrations ${TEST_GALA_WHERE}`);
            db.run(`DELETE FROM croatians_abroad_registrations ${TEST_CA_WHERE}`);
            db.run("INSERT INTO app_state (key, value, updated_at) VALUES ('gala_test_wipe_2026_06_03_v2', ?, ?)",
                [`gala_registrations:${gCount2},croatians_abroad_registrations:${caCount2}`, new Date().toISOString()]);
            console.log(`[wipe v2] Test-tagged data cleared: ${gCount2} gala + ${caCount2} croatians_abroad rows.`);
        }
        // Retire the old auto-seeded demo gala guests (8 fake VIPs incl. real public-figure
        // names that re-appeared on the live dashboard after each wipe). One-time, marker-gated.
        // Deletes only the exact seed rows (seed sentinel created_at + known emails) so a real
        // future registrant sharing an email is never touched.
        const galaSeedMarker = query.get("SELECT value FROM app_state WHERE key = 'gala_demo_seed_v1'");
        if (!galaSeedMarker) {
            const SEED_GALA_EMAILS = ['dragan.primorac@stcatherine.hr','miroslav.radman@inserm.fr','sarah.mitchell@hms.harvard.edu','michael.chen@mdanderson.org','elena.rossi@novartis.com','ana.kovacevic@mef.hr','hmueller@charite.de','ytanaka@keio.jp'];
            try {
                const ph = SEED_GALA_EMAILS.map(() => '?').join(',');
                db.run(`DELETE FROM gala_registrations WHERE created_at = '2026-01-20' AND email IN (${ph})`, SEED_GALA_EMAILS);
            } catch(e) { console.warn('[gala demo cleanup]', e.message); }
            db.run("INSERT INTO app_state (key, value, updated_at) VALUES ('gala_demo_seed_v1', 'cleaned', ?)", [new Date().toISOString()]);
            console.log('[gala] Demo guest seed retired.');
        }
    } catch(e) { console.warn('[wipe] Test-data wipe failed:', e.message); }

    // Seed default gala speakers and schedule if columns are empty
    const galaCheck = query.get("SELECT speakers_json FROM gala_settings WHERE id = 'default'");
    if (galaCheck && !galaCheck.speakers_json) {
        // Speakers are added through the admin gala editor once confirmed — never seed placeholder
        // names. An empty roster keeps the public gala page hidden-until-confirmed.
        const defaultGalaSpeakers = JSON.stringify([]);
        const defaultGalaSchedule = JSON.stringify([
            { time: '18:00', title: 'Welcome Reception', description: 'Champagne cocktails and canapes in the Grand Foyer', icon: 'fas fa-champagne-glasses' },
            { time: '19:00', title: 'Opening & Keynote Address', description: 'Keynote address to be announced', icon: 'fas fa-microphone' },
            { time: '20:00', title: 'Gala Dinner', description: 'Five-course dinner with premium wine pairings', icon: 'fas fa-utensils' },
            { time: '21:30', title: 'Biomedical Forum Annual Awards', description: 'Recognition of outstanding contributions to medical research', icon: 'fas fa-trophy' },
            { time: '22:30', title: 'Networking & Entertainment', description: 'Live music, dancing, and exclusive networking until midnight', icon: 'fas fa-users' }
        ]);
        db.run("UPDATE gala_settings SET speakers_json = ?, schedule_json = ? WHERE id = 'default'",
            [defaultGalaSpeakers, defaultGalaSchedule]);
    }

    // Plexus settings (admin-editable)
    db.run(`CREATE TABLE IF NOT EXISTS plexus_settings (
        id TEXT PRIMARY KEY DEFAULT 'default',
        price_student_early REAL DEFAULT 39,
        price_student_late REAL DEFAULT 59,
        price_professional_early REAL DEFAULT 99,
        price_professional_late REAL DEFAULT 149,
        key_dates_json TEXT,
        testimonials_json TEXT,
        conference_start_date TEXT DEFAULT '2026-12-04',
        conference_end_date TEXT DEFAULT '2026-12-05',
        early_bird_deadline TEXT DEFAULT '2026-09-30',
        abstract_deadline TEXT DEFAULT '2026-10-15',
        is_registration_open INTEGER DEFAULT 1,
        updated_at TEXT DEFAULT CURRENT_TIMESTAMP
    )`);
    // Conference identity fields — synced bidirectionally with `conferences` table
    try { db.run(`ALTER TABLE plexus_settings ADD COLUMN conference_name TEXT`); } catch(e) {}
    try { db.run(`ALTER TABLE plexus_settings ADD COLUMN conference_description TEXT`); } catch(e) {}
    try { db.run(`ALTER TABLE plexus_settings ADD COLUMN venue_name TEXT`); } catch(e) {}
    try { db.run(`ALTER TABLE plexus_settings ADD COLUMN venue_city TEXT`); } catch(e) {}
    try { db.run(`ALTER TABLE plexus_settings ADD COLUMN venue_country TEXT`); } catch(e) {}
    // Seed plexus_settings from conferences table on first run so admin sees current values
    try {
        const ps = query.get("SELECT conference_name, venue_name FROM plexus_settings WHERE id = 'default'");
        if (ps && !ps.conference_name) {
            const cf = query.get("SELECT * FROM conferences WHERE slug = 'plexus-2026'");
            if (cf) {
                db.run("UPDATE plexus_settings SET conference_name = ?, conference_description = ?, venue_name = ?, venue_city = ?, venue_country = ? WHERE id = 'default'",
                    [cf.name || 'Plexus Conference 2026', cf.description || '', cf.venue_name || 'Hotel Esplanade', cf.venue_city || 'Zagreb', cf.venue_country || 'Croatia']);
            }
        }
    } catch(e) {}

    // Seed default plexus settings if none exist
    const existingPlexusSettings = query.get("SELECT id FROM plexus_settings WHERE id = 'default'");
    if (!existingPlexusSettings) {
        const defaultKeyDates = JSON.stringify([
            { label: 'Early Bird Registration', date: 'Until September 30, 2026', color: 'var(--up-success)' },
            { label: 'Abstract Submission Deadline', date: 'October 15, 2026', color: 'var(--up-warning)' },
            { label: 'Conference', date: 'December 4-5, 2026', color: '#0f172a' }
        ]);
        // Testimonials start EMPTY — the member portal hides the section until real
        // consented quotes are added. Never seed fabricated people. (Mirrors user server.)
        db.run("INSERT INTO plexus_settings (id, key_dates_json, testimonials_json) VALUES ('default', ?, ?)",
            [defaultKeyDates, '[]']);
    }

    // One-time cleanup mirroring the user server: blank the row only if it still holds the
    // old fabricated seed (marker: 'Dr. Ana Markovic'). Real admin-added quotes untouched.
    try {
        const tRow = query.get("SELECT testimonials_json FROM plexus_settings WHERE id = 'default'");
        if (tRow && tRow.testimonials_json && tRow.testimonials_json.includes('Dr. Ana Markovic')) {
            db.run("UPDATE plexus_settings SET testimonials_json = '[]' WHERE id = 'default'");
            saveDb();
            console.log('[Cleanup] Removed fabricated seed testimonials from plexus_settings');
        }
    } catch (e) {}

    try { db.run(`ALTER TABLE forum_members ADD COLUMN checked_in INTEGER DEFAULT 0`); } catch(e) {}
    try { db.run(`ALTER TABLE forum_members ADD COLUMN checked_in_at TEXT`); } catch(e) {}

    // Per-event check-in toggle
    try { db.run(`ALTER TABLE sessions ADD COLUMN checkin_enabled INTEGER DEFAULT 0`); } catch(e) {}
    try { db.run(`ALTER TABLE forum_events ADD COLUMN checkin_enabled INTEGER DEFAULT 0`); } catch(e) {}
    try { db.run(`ALTER TABLE bridges_events ADD COLUMN checkin_enabled INTEGER DEFAULT 0`); } catch(e) {}

    // Phase 5B: Forum event management columns
    try { db.run(`ALTER TABLE forum_events ADD COLUMN is_published INTEGER DEFAULT 0`); } catch(e) {}
    try { db.run(`ALTER TABLE forum_events ADD COLUMN updated_at TEXT`); } catch(e) {}
    try { db.run(`ALTER TABLE forum_event_registrations ADD COLUMN name TEXT`); } catch(e) {}
    try { db.run(`ALTER TABLE forum_event_registrations ADD COLUMN email TEXT`); } catch(e) {}
    try { db.run(`ALTER TABLE forum_event_registrations ADD COLUMN institution TEXT`); } catch(e) {}

    // Phase 6A: Building Bridges publish + sync columns
    try { db.run(`ALTER TABLE bridges_events ADD COLUMN is_published INTEGER DEFAULT 0`); } catch(e) {}
    try { db.run(`ALTER TABLE bridges_events ADD COLUMN updated_at TEXT`); } catch(e) {}
    // Immutable slug — seeded by the user portal for the two invitation-only Plexus Week events
    // ('building-bridges' / 'donor-night'); rename-safe key used by check-in scoping below.
    try { db.run(`ALTER TABLE bridges_events ADD COLUMN slug TEXT`); } catch(e) {}

    // Phase 7: Per-event Bridges pricing (0 = free)
    try { db.run(`ALTER TABLE bridges_events ADD COLUMN price REAL DEFAULT 0`); } catch(e) {}
    try { db.run(`ALTER TABLE bridges_registrations ADD COLUMN payment_status TEXT DEFAULT 'n/a'`); } catch(e) {}
    try { db.run(`ALTER TABLE bridges_registrations ADD COLUMN amount_paid REAL`); } catch(e) {}
    // Account linking: a public Bridges/Donor Night registration made while logged in (or
    // claimed retroactively by email) attaches to the member's account. Nullable — the
    // anonymous path is untouched. Declared identically in BOTH portal server.js files.
    try { db.run(`ALTER TABLE bridges_registrations ADD COLUMN user_id TEXT`); } catch(e) {}

    // Phase 8: composable per-link pricing — selectable, individually-priced components
    // per event (admin edits prices; user portal reads them at checkout). Same table in
    // both backends per the dual-server pattern. Prices are gala-EXCLUDED per component.
    try { db.run(`CREATE TABLE IF NOT EXISTS event_components (
        id TEXT PRIMARY KEY,
        event_type TEXT NOT NULL,
        component_key TEXT NOT NULL,
        label TEXT NOT NULL,
        price REAL DEFAULT 0,
        sort_order INTEGER DEFAULT 0,
        is_active INTEGER DEFAULT 1,
        UNIQUE(event_type, component_key)
    )`); } catch(e) {}
    // Plexus 2026 (per the "3 events" invitation): Conference FREE, Bridges FREE, Gala paid.
    // Mirror of the user-portal seed so the admin link picker shows the same components.
    [
        ['plexus','conference','Plexus Conference (4–5 Dec)',0,1],
        ['plexus','bridges','Croatian Biomedical Bridges (4–5 Dec)',0,2],
        ['plexus','gala','Plexus Gala Evening (5 Dec)',150,3],
        ['plexus','reception','Welcome Reception',0,4],
        ['plexus','workshop','Workshop',0,5],
        ['forum','day1','Day 1 — Split',0,1],
        ['forum','day2','Day 2 — Zagreb',0,2],
        ['forum','gala','Gala Dinner',100,3],
    ].forEach(([et,key,label,price,sort]) => {
        try { db.run('INSERT OR IGNORE INTO event_components (id, event_type, component_key, label, price, sort_order, is_active) VALUES (?,?,?,?,?,?,1)',
            [et + '-' + key, et, key, label, price, sort]); } catch(e) {}
    });
    // Force the pre-existing Plexus Conference component to FREE + refresh labels (INSERT OR
    // IGNORE won't update existing rows). Guarded to the legacy default 150 so a deliberate
    // admin price edit is never stomped.
    try {
        const confRow = query.get("SELECT price FROM event_components WHERE event_type='plexus' AND component_key='conference'");
        if (confRow && Number(confRow.price) === 150) {
            db.run("UPDATE event_components SET price = 0, label = 'Plexus Conference (4–5 Dec)' WHERE event_type='plexus' AND component_key='conference'");
        }
        db.run("UPDATE event_components SET label = 'Plexus Gala Evening (5 Dec)' WHERE event_type='plexus' AND component_key='gala' AND label = 'Gala Evening'");
    } catch(e) {}

    // 2026-07-25 (Alen): the conference itself is FREE — money can only ever mean the Gala, so
    // invoices always say what was actually bought. One-time zeroing of the legacy paid
    // conference tiers (General Attendee 150/175, Student 75/100/125); tier names stay for
    // badges and registration. app_state-guarded so a future deliberate admin price edit is
    // never stomped by a restart.
    try {
        const freeConfDone = query.get("SELECT value FROM app_state WHERE key = 'migration_free_conference_tiers'");
        if (!freeConfDone) {
            db.run('UPDATE ticket_types SET price_early_bird = 0, price_regular = 0, price_late = 0');
            db.run("INSERT OR REPLACE INTO app_state (key, value) VALUES ('migration_free_conference_tiers', datetime('now'))");
            saveDb();
            console.log('[Migration] Conference ticket tiers zeroed — the conference is free, only the Gala is paid');
        }
    } catch(e) { console.warn('[Migration] free-conference-tiers failed:', e.message); }


