    try { db.run("ALTER TABLE user_notifications ADD COLUMN expires_at TEXT"); } catch(e) {}
    try { db.run("ALTER TABLE user_notifications ADD COLUMN placement TEXT DEFAULT 'panel'"); } catch(e) {}

