            db.run(`INSERT INTO template_library (id, name, subject, body_html, category, project, variables) VALUES (?, ?, ?, ?, ?, ?, ?)`,
                [uuidv4(), t.name, t.subject, t.body_html, t.category, t.project, t.variables]);
