    // CSV cell sanitization — prevents formula injection (=, +, -, @, tab, carriage return)
    function sanitizeCsvCell(value) {
        if (value === null || value === undefined) return '';
        const str = String(value);
        if (/^[=+\-@\t\r]/.test(str)) return "'" + str;
        return str;
    }

